<script setup lang="ts">definePageMeta({ middleware: 'auth' }); const route = useRoute(); const id = Number(route.params.id); const { list } = useGrades(); const { data: enrollments } = await useAsyncData(`roster-${id}`, () => list(id))</script>
<template><div class="page-shell"><PageHeader :title="`Course offering #${id}`" description="Class roster"><template #actions><BaseButton :to="`/my-course-offerings/${id}/grades`">Manage grades</BaseButton></template></PageHeader><BaseCard><div v-for="item in enrollments" :key="item.id" class="border-t border-slate-100 py-3"><p class="font-semibold">{{ item.student?.last_name }}, {{ item.student?.first_name }}</p><p class="text-sm text-slate-500">{{ item.student?.student_number }}</p></div></BaseCard></div></template>
